BetSetData.source:
function (betData) {
            this.defaultBetIndex = this.currentBetIndex = betData.getDefaultIndex();
            var betDatas = betData.getAvailableBetArray();
            this.bets = [];
            var lineCount;
            for (var i = 0; i < betDatas.length; i++) {
                lineCount = this._paylinecountController.getLines()[i] / 2;
                this.bets[i] = [];
                for (var j = 0; j < betDatas[i].length; j++) {
                    var betMultiplier = betDatas[i][j] / lineCount;
                    this.bets[i].push(new sgigame.Bet(betDatas[i][j], betMultiplier));
                }
            }
        }

